BIB_ATTRS = ['title', 'summary', 'creator_name']

# %% ../nbs/api/metadata.ipynb #6777d403
def fetch_zotero(
    item_id:str, # Zotero item key to retrieve
    lib_id:str, # Zotero library ID
    api_key:str # Zotero API key
) -> dict|None: # Zotero item, or None if the item does not exist
    "Fetch an item from a Zotero group library"
    try: return zotero.Zotero(lib_id, 'group', api_key).item(item_id)
    except zotero_errors.ResourceNotFoundError: return None

# %% ../nbs/api/metadata.ipynb #761032af
class ZoteroClient:
    "Zotero API client to fetch a bibliographic record"
    def __init__(self,
        item_id: str, # Zotero item key to retrieve
        lib_id: str,  # Zotero library ID
        api_key: str  # Zotero API key
    ) -> None:
        store_attr()
        self.item = fetch_zotero(item_id, lib_id, api_key)

    def exist(self) -> bool: return self.item is not None

    def _get(self,
        key:str # Zotero data key to retrieve
    ) -> str: # Value for that key, or '' if item not loaded
        return self.item['data'][key] if self.item else ''

    @property
    def title(self) -> str: return self._get('title')

    @property
    def summary(self) -> str: return self._get('abstractNote')

    @property
    def creator_name(self) -> str: return json.dumps(self._get('creators')) if self.item else ''

    def __repr__(self): return json.dumps(self.item, indent=4)

# %% ../nbs/api/metadata.ipynb #1328e775
class ZoteroCB(Callback):
    "Populate global attributes from Zotero bibliographic metadata"
    def __init__(self,
        item_id:str, # Zotero item key to retrieve
    ): store_attr()
    def __call__(self, obj):
        item = ZoteroClient(self.item_id, ZOTERO_LIB_ID, os.getenv('ZOTERO_API_KEY'))
        if item.exist():
            obj.attrs['id'] = item.item['key']
            for attr in BIB_ATTRS: obj.attrs[attr] = getattr(item, attr)

