def fetch_inis(
    inis_id:str,   # INIS record identifier (e.g. 'vq0ha-86k24')
    base_url:str=INIS_API # API root
) -> dict|None: # Raw INIS record payload, or None if the record does not exist
    "Fetch an INIS record"
    return fetch_record(inis_id, base_url)

# %% ../nbs/api/metadata.ipynb #ac02991e
class INISClient:
    "Retrieve INIS metadata from the InvenioRDM API"
    def __init__(self,
        inis_id:str,   # INIS record identifier (e.g. 'vq0ha-86k24')
        base_url:str=INIS_API # API base URL
    ) -> None:
        store_attr()
        self.item = fetch_inis(inis_id, base_url)
        self.metadata = (self.item or {}).get('metadata', {})

    def exist(self) -> bool: return self.item is not None

    @property
    def title(self) -> str: return self.metadata.get('title') or ''

    @property
    def summary(self) -> str: return self.metadata.get('description') or ''

    @property
    def creator_name(self) -> str:
        return json.dumps(self.metadata.get('creators', []), ensure_ascii=True) if self.item else ''

# %% ../nbs/api/metadata.ipynb #046ac806
@patch(as_prop=True)
def doi(self:INISClient) -> str:
    "DOI of the record, or '' if it has none"
    doi = (self.item or {}).get('pids', {}).get('doi', {})
    if isinstance(doi, dict): doi = doi.get('identifier') or ''
    if doi: return doi
    for ident in self.metadata.get('identifiers', []):
        if ident.get('scheme') == 'doi': return ident.get('identifier', '')
    return ''

# %% ../nbs/api/metadata.ipynb #0fe913c1
@patch(as_prop=True)
def url(self:INISClient) -> str:
    "Web page of the record, or '' if it has none"
    links = (self.item or {}).get('links', {})
    return links.get('self_html') or links.get('latest_html') or links.get('self', '')

# %% ../nbs/api/metadata.ipynb #fd6f5646
class InisCB(Callback):
    "Populate global attributes from INIS metadata"
    def __init__(self,
        inis_id:str, # INIS record identifier to retrieve
        base_url:str=INIS_API # API base URL
    ): store_attr()
    def __call__(self, obj):
        item = INISClient(self.inis_id, self.base_url)
        if item.exist():
            obj.attrs['id'] = self.inis_id
            for attr in BIB_ATTRS: obj.attrs[attr] = getattr(item, attr)
            if item.doi: obj.attrs['references'] = item.doi
            if item.url: obj.attrs['metadata_link'] = item.url
